struct PolicyA { 
    static int op(int x) { return x * 2; } 
};
struct PolicyB { 
    static int op(int x) { return x + 10; } 
};

template <typename P>
class Processor {
public:
    int execute(int val) const {
        // Static dispatch based on template arg P
        // Compiler inlines P::op(val) directly
        return P::op(val);
    }
};

// Example instantiation forces code generation:
// Processor<PolicyA> p1; // Specialization A created (x * 2)
// Processor<PolicyB> p2; // Specialization B created (x + 10)
// No runtime overhead (no VTABLE lookups).
